<script lang="ts">export let checked=false; export let label=''; export let disabled=false; export let name=''; export let onChange:(value:boolean)=>void=()=>{};</script>
<label class="toggle"><span>{label}</span><input type="checkbox" {name} bind:checked {disabled} onchange={()=>onChange(checked)}/><i aria-hidden="true"></i></label>
<style>.toggle{display:inline-flex;align-items:center;gap:10px;cursor:pointer}.toggle input{position:absolute;opacity:0;width:1px;height:1px}.toggle i{width:34px;height:19px;border-radius:12px;background:#c7ced8;position:relative;transition:.15s}.toggle i:after{content:'';position:absolute;width:15px;height:15px;left:2px;top:2px;border-radius:50%;background:white;transition:.15s}.toggle input:checked+i{background:var(--accent)}.toggle input:checked+i:after{transform:translateX(15px)}.toggle input:focus-visible+i{outline:3px solid #2866df35}</style>
